 document.addEventListener('DOMContentLoaded', () => {
     const disclosureButtons = document.querySelectorAll('button[aria-expanded]');

     disclosureButtons.forEach(button => {
         const panelId = button.getAttribute('aria-controls');
         const panel = document.getElementById(panelId);

         // Initialize state: collapse by default
         // We do this in JS so if JS fails, the content is still visible.
         button.setAttribute('aria-expanded', 'false');
         if (panel) {
             panel.hidden = true;
         }

         button.addEventListener('click', () => {
             const isExpanded = button.getAttribute('aria-expanded') === 'true';
             const newExpandedState = !isExpanded;

             button.setAttribute('aria-expanded', String(newExpandedState));
             if (panel) {
                 panel.hidden = isExpanded; // if it was expanded, hide it; if it was hidden, show it
             }
         });
     });
 });

