            display: flex;
            font-size: 1.25rem;
            font-weight: 600;
            padding: 1rem 1.5rem;
            text-align: left;
            width: 100%;
            align-items: center;
            justify-content: space-between;
            transition: background-color 0.2s;
        }

        .example button:hover {
            background-color: rgba(255, 255, 255, 0.05);
        }

        .example button:focus-visible {
            outline: 2px solid var(--focus-outline);
            outline-offset: -2px;
        }

