        .example button::after {
            content: '';
            display: inline-block;
            width: 0.5em;
            height: 0.5em;
            border-right: 2px solid var(--text-muted);
            border-bottom: 2px solid var(--text-muted);
            transform: rotate(45deg);
            transition: transform 0.2s;
            margin-left: 1rem;
        }

